.hero01 {
  --hero01-media-background: var(--brand-primary);
  --hero01-media-text: var(--text-on-brand);
  --hero01-min-height: calc(var(--space-4) * 27.25);
  --hero01-copy-padding: var(--hero-content-padding);
  --hero01-copy-surface: var(--surface-base);
  width: 100%;
  color: var(--text-primary);
  font-family: var(--font-family-body);
}
.hero01 *, .hero01 *::before, .hero01 *::after { box-sizing: border-box; }
.hero01 p, .hero01 h1, .hero01 h2, .hero01 h3 { margin: 0; }
.hero01 .hero01-panels { gap: 0; min-height: var(--hero01-min-height); border-radius: var(--section-radius); overflow: hidden; }
.hero01 .hero01-copy { flex: 1.1 1 0; min-width: 0; padding: var(--hero01-copy-padding); background: var(--hero01-copy-surface); gap: 0; }
.hero01-eyebrow { font-size: var(--typography-micro-size); font-weight: var(--font-weight-semibold); letter-spacing: var(--letter-spacing-widest); }
.hero01-dot { width: calc(var(--space-4) * 0.375); height: calc(var(--space-4) * 0.375); border-radius: var(--radius-full); background: var(--brand-primary); }
.hero01 .hero01-copy :is(h1,h2,h3) { margin-block: var(--space-8) var(--space-6); font-size: var(--typography-hero-size); line-height: var(--line-height-tight); letter-spacing: var(--letter-spacing-tighter); overflow-wrap: anywhere; }
.hero01-title-line { display: block; }
.hero01-copy > p { max-width: var(--content-width-narrow); font-size: var(--typography-caption-size); line-height: var(--line-height-relaxed); }
.hero01 .hero01-cta { min-width: calc(var(--space-4) * 12.5); margin-block: var(--space-6) var(--space-8); text-decoration: none; }
.hero01-cta:focus-visible { outline: var(--focus-ring-width) solid var(--focus-ring-color); outline-offset: var(--focus-ring-offset); }
.hero01-footnote { margin-block-start: auto; font-size: var(--typography-micro-size); letter-spacing: var(--letter-spacing-widest); line-height: var(--line-height-relaxed); }
.hero01 .hero01-media { position: relative; isolation: isolate; flex: 1 1 0; min-width: 0; min-height: var(--hero01-min-height); padding: var(--card-padding); overflow: hidden; background: var(--hero01-media-background); color: var(--hero01-media-text); }
.hero01-media::before { content: ''; position: absolute; z-index: -1; inset: calc(var(--space-4) * 2) calc(var(--space-4) * -5); border-block: var(--border-width-thin) solid color-mix(in srgb, var(--hero01-media-text) 20%, transparent); transform: rotate(-15deg); }
.hero01-media::after { content: ''; position: absolute; z-index: -1; inset-inline-start: var(--space-6); top: 35%; width: calc(var(--space-4) * 11); height: calc(var(--space-4) * 11); border: var(--border-width-thin) solid color-mix(in srgb, var(--hero01-media-text) 20%, transparent); border-radius: var(--radius-full); }
.hero01-media-eyebrow { font-size: var(--typography-micro-size); letter-spacing: var(--letter-spacing-widest); }
.hero01-art { display: grid; place-items: center; flex: 1; min-height: calc(var(--space-4) * 16); min-width: 0; }
.hero01-art > .media { width: 100%; max-width: calc(var(--space-4) * 24); }
.hero01-art img { max-height: calc(var(--space-4) * 19); object-fit: contain; }
.hero01-monogram { font-size: var(--typography-display-size); font-weight: var(--font-weight-bold); letter-spacing: var(--letter-spacing-tighter); }
.hero01 .hero01-caption { gap: var(--inline-gap); font-size: var(--typography-micro-size); letter-spacing: var(--letter-spacing-widest); }
.hero01 .hero01-highlights { gap: var(--stack-gap); padding: var(--space-5) var(--space-6); border-block-end: var(--border-width-thin) solid var(--border-default); font-size: var(--typography-micro-size); font-weight: var(--font-weight-semibold); letter-spacing: var(--letter-spacing-widest); }
@media (max-width: 48rem) {
  .hero01 { --hero01-copy-padding: var(--card-padding); --hero01-min-height: calc(var(--space-4) * 21); }
  .hero01 .hero01-panels { flex-direction: column; }
  .hero01 .hero01-copy { flex-basis: auto; }
  .hero01 .hero01-copy :is(h1,h2,h3) { font-size: var(--typography-hero-size); }
  .hero01 .hero01-highlights { justify-content: flex-start; }
}

.hero01-media :is(.text-primary, .text-muted) { color: var(--hero01-media-text); }

export interface Hero01Props {
  eyebrow?: string;
  titleLines?: readonly string[];
  description?: string;
  ctaLabel?: string;
  ctaHref?: string;
  footnote?: string;
  mediaEyebrow?: string;
  mediaCaption?: string;
  mediaCredit?: string;
  imageSrc?: string;
  imageAlt?: string;
  highlights?: readonly string[];
  headingLevel?: "h1" | "h2" | "h3";
}
